INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (101, 117, 'BOPS window envelope film (Biaxially oriented polystyrene film)', '../upload/image/20181226/20181226113812_30346.jpg', '<p></p><p><span style="color:#009900;">BOPS window envelope film (Biaxially oriented polystyrene film)</span></p> <p><span style="color:#009900;">1. BOPS window envelope film (environmental protection type) </span><br/> <span style="color:#009900;"> BOPS film including BOPS window envelope film,BOPS film, BOPS shrink film</span><br/> <span style="color:#009900;"> 2. Feature of BOPS film:</span><br/> <span style="color:#009900;"> - Has a very good anti-static ability. </span><br/> <span style="color:#009900;"> - The smoothness of a good film, the production process in an envelope will rarely produce </span><br/> <span style="color:#009900;"> a result of thin film and mechanical standstill. </span><br/> <span style="color:#009900;"> - Film slitting good, with high-intensity endurance, meanwhile horizontally easily torn, </span><br/> <span style="color:#009900;"> very suitable for the production of high-speed operation of the envelope. </span><br/> <span style="color:#009900;"> - Low-cost, in China and Japan are using the standard 25um thickness, and other companies </span><br/> <span style="color:#009900;"> produced BOPS Materials 27um, 29um, compared the cost of a cheap film envelopes 8% ~ 16%.</span><br/> <span style="color:#009900;"> 3. Spec. sizes of BOPS film :</span><br/> <span style="color:#009900;"> BOPS film (Biaxially oriented polystyrene film),</span><br/> <span style="color:#009900;"> Normal Roll sizes for BOPS film:25UM*105,110,120,125,130,135MM*4000M</span><br/> <span style="color:#009900;"> Density :1.04(g/CM3) Color: Clear/ transparent or printed color logos</span><br/> <span style="color:#009900;"> Thickness of BOPS film: 27 g/m2 ( 30 Microns ),29 g/m2 ( 32 Microns),35 g/m2 ( 39 Microns),</span><br/> <span style="color:#009900;"> Width of BOPS film rolls:100,105,115,120,125,130,135,150 MM. Length of BOPS film rolls:3000-4000M .</span><br/> <span style="color:#009900;"> BOPS were most suitable use for the envelope window film thin, a very perfect read rates, can improve efficiency, thereby creating economic benefits. Whether it </span><br/> <span style="color:#009900;"> is an envelope manufacturer, bulk mail, the mail sorting business, postal operators, OPS </span><br/> <span style="color:#009900;"> film can bring you better work efficiency and economic benefits.</span></p>', '2026-09-06 20:58:45');